type AnalyticsEvent = {
  path: string
  timestamp: number
}

export async function logPageView(path: string): Promise<void> {
  const event: AnalyticsEvent = {
    path,
    timestamp: Date.now(),
  }

  await fetch("https://analytics.example.com/pageview", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(event),
  })
}

